        return "0\n-1"

    start_word = dictionary[0]
    end_word = dictionary[1]
    word_dict = set(dictionary[2:])

    # Find the shortest path without adding any word
    shortest_path = bfs_words(start_word, end_word, word_dict)

    min_steps = shortest_path
    best_word = "0"

    if min_steps == -1 or min_steps == 0:
        return f"0\n-1"

    # Check each possible word to be added
    possible_words = sorted(set(''.join(generate_neighbors(word)) for word in word_dict))
    for word_to_add in possible_words:
        if word_to_add not in word_dict:
            new_word_dict = word_dict.copy()
