        return count_diff == 1

    # Create an adjacency list
    adj_list = defaultdict(list)

    # Add a virtual node that connects to all words differing by one letter
    all_words = list(words_set)
    virtual_nodes = set()

    # Create adjacency list with real words and virtual nodes
    for word in all_words:
        for i in range(len(word)):
            for char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
                if word[i] != char:
                    neighbor = word[:i] + char + word[i+1:]
                    if neighbor in words_set:
                        adj_list[word].append(neighbor)
                    else:
                        adj_list[word].append(neighbor)
                        virtual_nodes.add(neighbor)

    # Modified BFS to include virtual nodes
    def bfs_with_virtual_nodes(start, end):
        queue = deque([(start, 0)])  # (word, steps)
        visited = set([start])

        while queue:
            current, steps = queue.popleft()
            if current == end:
                return steps

            for neighbor in adj_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, steps + 1))

        return float('inf')

    # Check the current shortest path
    min_steps = bfs_with_virtual_nodes(start, end)
    best_word = "0"

    # Try adding each virtual node (word) to the dictionary
    for word in sorted(virtual_nodes):
        if word not in words_set:
            words_set.add(word)
            new_min_steps = bfs_with_virtual_nodes(start, end)
            words_set.remove(word)

            if new_min_steps < min_steps:
                min_steps = new_min_steps
                best_word = word

    if min_steps == float('inf'):
        return "0", -1
    return best_word, min_steps

